SELECT CASE WHEN discount_pct >= 0.35 THEN 'PREMIUM' ELSE 'STANDARD' END AS discount_pct_tier, DATE_TRUNC('WEEK', ends_on) AS week_start, COUNT(*) FILTER (WHERE channel = 'store') AS store_rows, COUNT(CASE WHEN channel = 'mobile' THEN 1 END) AS mobile_count FROM promotions GROUP BY GROUPING SETS ((CASE WHEN discount_pct >= 0.35 THEN 'PREMIUM' ELSE 'STANDARD' END, DATE_TRUNC('WEEK', ends_on)), (CASE WHEN discount_pct >= 0.35 THEN 'PREMIUM' ELSE 'STANDARD' END)) HAVING COUNT(*) FILTER (WHERE channel = 'store') < 1 ORDER BY discount_pct_tier;
